add("YM-020","终局：寅命妻病凶、难愈（单一终局）。依据：妻财子水两现，初爻财动化官鬼寅木泄水，三爻兄弟辰土动克水且辰为子水之墓，财动入墓（随墓章本例门类）；巳建癸未日火土并旺，财休囚受克入墓三重压制，等级足断难愈。应期双层：窗口为本旬内（日档，近病日尺度），主坐标取辰日（财入墓逢值之日）为危日；三路：逢值辰日取之、冲实戌日冲辰为出墓备选舍（出墓在危日之后、不足以翻终局）、填实无空，注明。对象复述：承受与应验对象均为占者之妻（寅命），一致。",L+"；山天大畜之山水蒙。用神妻财子水。动化方向：子水化寅木泄、辰土化午火。反转条件：财出墓得生才翻，本盘动入墓不翻。双闸复核已过。",0.70)
add("YM-022","终局：身命有厄、此期不吉（单一终局）。依据：世爻官鬼午火动化父母戌土，午火入戌墓且泄气；上爻父母戌土动化妻财寅木，戌土动而叠墓。年命戊午与世爻午火同气，厄应本人。应期双层：窗口以年为界（年档，身命吉凶以年为尺度，先定年），主坐标取戌年（墓库逢值之年）为应厄之年，年内不径落日；三路：逢值戌年取之、冲实辰年冲戌为解墓备选舍（解墓主缓、不翻本期不吉）、填实无空，注明。对象复述：承受与应验对象均为戊午生人本人，一致。",L+"；雷山小过之艮。用神取世与年命午火。动化方向：午火化戌土入墓、戌土化寅木。反转条件：午火出墓得生才翻吉，本盘入墓不翻。双闸复核已过。",0.55)
add("YM-023","终局：可贵可仕、得官有位，但等级为中等贵显非极贵（单一终局）。依据：官鬼寅木临应旺于寅建、官鬼卯木二爻亦动，官星两现而旺主贵气有据；然卯木动化父母巳火泄官、初爻父母巳火动化兄弟未土，官气被泄一层，故按等级校准降一级并写明压制依据为官化泄。应期双层：窗口以年为界（年档，功名贵显以年为尺度），主坐标取卯年（官星逢值之年）为得位之年；三路：逢值卯年取之、合冲引动无据、填实无墓，注明。",L+"；山泽损之山地剥。用神官鬼。动化方向：卯木化巳火泄、巳火化未土。反转条件：官化进得生才升格，本盘化泄故只降格不翻败。双闸复核已过。",0.55)
add("YM-024","终局：将晴（单一终局）。依据：天时占以子孙主晴、妻财主雨，本卦妻财不上卦，子孙酉金持世；初爻父母丁巳火（雨象之父）动化官鬼寅木，巳火得寅木回头生似主雨，然世爻子孙居尊位主晴终胜，雨象退居初爻。应期双层：窗口为二日内（日档，天时以日为尺度），主坐标取酉日（子孙逢值之日）转晴；三路：逢值酉日取之、冲实卯日冲酉舍（占日即卯日、冲世反主当日未晴，与次序相合故不取为晴点）、填实无空，注明。近远两段：近段当日仍阴（卯日冲世），远段酉日晴，触发为子孙逢值，已并入终局。",L+"；火泽睽之火水未济。动化方向：巳火化寅木回头生。反转条件：财爻出现旺动才翻雨，本盘财伏不现不翻。双闸复核已过。",0.55)
add("YM-025","终局：明日有雨（单一终局）。依据：静卦火山旅六合，妻财酉金临应、妻财申金居四爻，财爻两现主阴雨之象（天时以财主雨）；兄弟巳火午火虽主晴意，皆静而不动，压不过两财临位。应期双层：窗口为次日一日（日档，题面明问明日，日尺度理由为题面本身），主坐标即次日（甲寅日之次日乙卯日）有雨；三路：逢值以题面指定日为点取之、冲实填实静卦无动无空，注明无候选。",L+"；火山旅静卦。用神妻财（雨象）。动化方向：静卦无动化。反转条件：无动爻可翻。双闸复核已过。",0.60)
add("YM-027","终局：晴来迟、先雨后晴，秋成仅平常（单一终局取晴迟）。依据：父母午火二爻动主雨象发动，化兄弟辰土；世爻子孙申金动化父母午火回头克，晴象之子孙动而化雨象且受克，晴必迟；子孙受损兼主秋成不丰。应期双层：窗口为本旬内（日档，天时日尺度），主坐标取午日之后申日（子孙本宫逢值）为转晴点，午日为雨盛点已入近段；三路：逢值申日取之、冲实寅日冲申舍（主晴象被冲、与转晴相悖）、填实无空，注明。近段雨、远段晴，远段触发为子孙申金逢值，已指认。",L+"；风山渐之风水涣。用神子孙（晴）父母（雨）对决。动化方向：午火化辰土、申金化午火回头克。反转条件：子孙化进才翻速晴，本盘回头克不翻。双闸复核已过。",0.50)
add("YM-028","终局：为父母觅地不得即时得地、须迟候（单一终局取未得）。依据：静卦天地否六合，父母戌土临应旺于丁未日土气，父母未土亦现，地之文书虽有，世爻妻财卯木克父母主求者与地未合、否卦主闭塞不通。应期双层：窗口以年内为界（年档，茔葬觅地以年月为尺度），主坐标取戌月（父母逢值之月）为再得消息之期，本期先断未得；三路：逢值戌月取作复核点、冲实填实静卦无动，注明。对象复述：承受对象为其父母之茔地、应验对象同为该地（非人对象），一致。",L+"；天地否静卦。用神父母。动化方向：静卦无动化。反转条件：无动爻，世克用神不翻。双闸复核已过。",0.55)
add("YM-029","终局：此地不可用、就地不成（单一终局）。依据：静卦山天大畜，父母不上卦（茔地之用神伏藏不出），地无凭据主不可据以安葬；妻财子水两现临应与初爻，财旺克父之象亦同向。应期双层：本题问可用否为单点终局、无成事应期可报，明写无应期（月档尺度下只给终局，不造日期）；三路：逢值冲实填实皆因用神伏藏无点可取，逐路注明无候选。对象复述：承受与应验对象均为该地本身（非人对象），一致。",L+"；山天大畜静卦。用神父母伏藏为弱点，已降置信。动化方向：静卦无动化。反转条件：父母出伏才翻可用，本盘静伏不翻。双闸复核已过。",0.55)
add("YM-030","终局：胎安（单一终局）。依据：子孙亥水居四爻，申建辛亥日金水并旺，胎神旺相得日月生扶；初爻官鬼巳火动化妻财寅木，官动化财不克子孙（金水旺、火囚于申月）。应期双层：本题问胎安否为状态终局，临盆非所问，明写应期只到安定期：本孕期内安（月档），不另造产日；三路：逢值亥月主胎旺已取作安定期坐标、冲实巳日冲亥为动胎备选舍（官动已化财泄火，不作凶点）、填实无空，注明。对象复述：承受对象为孕妇之胎、应验同此，一致。",L+"；泽兑之泽水困。用神子孙亥水。动化方向：巳火化寅木。反转条件：子孙受冲克才翻不安，本盘旺相不翻。双闸复核已过。",0.70)
add("YM-032","终局：所怀为男胎、且可育成（单一终局）。依据：静卦雷泽归妹，子孙不上卦为弱点；按胎产取象，卦中官鬼午火巳火阳爻得位、世应阴阳配置以阳象占先，故断男；子孙伏藏不断育绝，因父母兄弟俱全、卦体无冲克胎位之动。应期双层：本题问性别为单点终局，无应期可报，明写无应期；三路皆因静卦无动、子孙伏藏无点可取，逐路注明。对象复述：承受与应验对象均为孕妇之胎，一致。",L+"；雷泽归妹静卦。子孙伏藏，输入信息弱，已降置信至本批低位。动化方向：静卦无动化。反转条件：无动爻可翻，性别断语仅凭阳象占先，置信已压低。双闸复核已过。",0.50)
add("YM-033","终局：复卜后嗣可得、有子之望转为实（单一终局）。依据：静卦泽地萃，子孙亥水居四爻，丁亥年仲春卯建甲申日申金生水，子孙得日生而静守萃聚之卦，主嗣可聚于家；与初占无子之旧断相较，本盘子孙得生为转机之据（旧断仅作题面事实，不作本盘证据）。应期双层：窗口以年为界（年档，求嗣以年为尺度，先定年），主坐标取亥年（子孙逢值之年）为得子应期之年；三路：逢值亥年取之、合冲引动无据、填实无墓，注明。",L+"；泽地萃静卦。用神子孙亥水。动化方向：静卦无动化。反转条件：子孙受克才翻仍无，本盘得申金生不翻。双闸复核已过。",0.60)
add("YM-034","终局：痘将发（单一终局取发）。依据：官鬼卯木临应动主痘病发动，化兄弟丑土；三爻兄弟丑土动化妻财亥水。子孙申金持世旺于丑建土生，世旺主本体可承，发而势不至绝。应期双层：窗口为本旬内（日档，痘发近事日尺度），主坐标取卯日（官鬼逢值之日）发痘；三路：逢值卯日取之、冲实酉日冲卯舍（占日乙卯、逢值先于逢冲）、填实无空，注明。对象复述：承受与应验对象均为该孩童，一致。近段发、远段安危：远段无独立触发，明写一段终局，远段无据不报。",L+"；天泽履之天火同人。用神官鬼（痘病）子孙（本体）合参。动化方向：卯木化丑土、丑土化亥水。反转条件：官鬼化绝才翻不发，本盘官动临应不翻。双闸复核已过。",0.60)
add("YM-035","终局：痘将发、发而势轻可安（单一终局）。依据：子孙申金持世独动化兄弟未土回头生，本体动而得生主痘透发有根；父母午火居四爻为痘火之象，静而不烈。应期双层：窗口为本旬内（日档），主坐标取申日（子孙逢值之日）透发；三路：逢值申日取之、冲实寅日冲申舍（主反复、与透发终局相悖）、填实无空，注明。对象复述：承受与应验对象均为该孩童，一致。",L+"；天泽履之火泽睽。用神子孙申金世动。动化方向：申金化未土回头生。反转条件：子孙化克才翻凶，本盘回头生不翻。双闸复核已过。",0.60)
add("YM-037","终局：子痘凶、病势重难安（单一终局）。依据：子孙寅木持世，未建甲辰日木休土旺，父母申金四爻动克寅木、化兄弟亥水，官鬼辰土三爻动亦克耗，子孙受金克而无生扶（水爻兄弟子水静而不动）。应期双层：窗口为本旬内（日档），主坐标取申日（克子之金逢值之日）为危日；三路：逢值申日取之、冲实寅日即世爻逢值舍（值日不敌动克）、填实无空，注明。对象复述：承受与应验对象均为占者之子，一致。",L+"；水雷屯之泽火革。用神子孙寅木世。动化方向：辰土化亥水、申金化亥水。反转条件：子孙得水动生才翻安，本盘水静不翻。双闸复核已过。",0.60)
add("YM-038","终局：子病可愈（单一终局）。依据：静卦天火同人，子孙戌土临应、子孙丑土居二爻，戌建甲辰日土旺，子孙两现旺相克制世爻官鬼亥水（水囚于土旺之时），用神旺而病神囚主愈。年命己亥与官鬼亥水同支为病位所在，已对回本人（病者为子、年命即子之命），对象一致。应期双层：窗口为本旬内（日档，近病日尺度），主坐标取戌日（子孙逢值之日）见愈；三路：逢值戌日取之、冲实辰日冲戌舍（占日辰日已冲一现、不作愈点）、填实无空，注明。",L+"；天火同人静卦。用神子孙。动化方向：静卦无动化。反转条件：无动爻，子孙旺相不翻。双闸复核已过。",0.65)
add("YM-039","终局：妻病重、难愈（单一终局）。依据：静卦离为火六冲，妻财酉金居四爻，癸卯岁卯建壬子日木旺水泄，酉金囚于卯月、又受世爻兄弟巳火克，财休囚受克且六冲主散。应期双层：窗口为本旬内（日档，近病日尺度），主坐标取酉日（妻财逢值之日）为关口；三路：逢值酉日取之、冲实卯日冲酉舍（占日后卯日再临为加重非转机）、填实无空，注明。对象复述：承受与应验对象均为程良玉之妻，一致。",L+"；离为火静卦。用神妻财酉金。动化方向：静卦无动化。反转条件：财得土金生扶才翻，本盘无动扶不翻。双闸复核已过。",0.65)
add("YM-040","终局：夫病可愈、转危为安（单一终局）。依据：子孙戌土临应动克官鬼（病神），主药力与转机发动；官鬼亥水持世虽休于未建壬寅日，子孙动来制病为愈之主据。然戌土化官鬼子水回头生病神，故近段先愈缓、反复一层，终局仍取可愈并写明此压制。应期双层：窗口为本月内（月档坐标落在旬窗，近病以旬为上限量级），主坐标取戌日（子孙逢值之日）见转机；三路：逢值戌日取之、冲实辰日冲戌舍（冲动子孙主药力散、与愈终局相悖）、填实无空，注明。对象复述：承受与应验对象均为占者之夫，一致。",L+"；天火同人之水火既济。用神官鬼亥水世（夫）、子孙为药。动化方向：午火化申金、戌土化子水回头生官。反转条件：子孙化生病神本为翻凶候选，但子孙动克在先、化水仅缓愈速，未过终局反转三信号全立门槛，故只降格不反向断凶。双闸复核已过。",0.50)
add("YM-042","终局：妻病缠绵但可愈、不致丧亡（单一终局取可愈）。依据：静卦水火既济，妻财不上卦伏藏为弱点（已降置信）；伏财午火一系得午建戊寅日木火之气，伏而得生不绝；官鬼两现皆土，病势以土湿缠绵论，不克绝伏财。应期双层：窗口以月为界（月档，缠绵之病以月为尺度），主坐标取午月（伏财逢值出伏之月）为见愈之期；三路：逢值午月取之、冲实子月冲午舍（主反复）、填实无墓，注明。对象复述：承受与应验对象均为占者之妻，一致。",L+"；水火既济静卦。用神妻财伏藏，信息弱已降置信。动化方向：静卦无动化。反转条件：伏财受冲克绝才翻凶，本盘伏得月日生气不翻。双闸复核已过。",0.50)
add("YM-043","终局：父病重、难愈（单一终局）。依据：父母午火二爻独动，戌建为火之墓库，午火动入戌墓；且化妻财亥水回头克，用神动而入墓化克，病占父母大忌叠见，等级足断难愈。应期双层：窗口为本旬内（日档，近病日尺度），主坐标取午日（父母逢值之日）为危日；三路：逢值午日取之、冲实子日冲午舍（冲动入墓之爻不作转机）、填实戌日即墓值已在占时结构内不另立，注明。对象复述：承受与应验对象均为占者之父，一致。",L+"；艮为山之山风蛊。用神父母午火动。动化方向：午火化亥水回头克。反转条件：父母出墓得生才翻，本盘入墓化克不翻。双闸复核已过。",0.70)
IDS21=["WP-008","WP-009","WP-010","WP-011","WP-012","WP-013","YM-002","YM-003","YM-004","YM-005","YM-007","YM-008","YM-009","YM-010","YM-012","YM-013","YM-014","YM-015","YM-017","YM-018"]
IDS22=["YM-019","YM-020","YM-022","YM-023","YM-024","YM-025","YM-027","YM-028","YM-029","YM-030","YM-032","YM-033","YM-034","YM-035","YM-037","YM-038","YM-039","YM-040","YM-042","YM-043"]
assert set(IDS21+IDS22)==set(P), (set(IDS21+IDS22)^set(P))
for batch,ids in (("B21",IDS21),("B22",IDS22)):
    assert len(ids)==20
    for cid in ids:
        pt,basis,conf,trig=P[cid]
        rec={"case_id":cid,"prediction_text":pt,"basis":basis,"confidence":conf,"trigger":trig}
        with open(os.path.join(BASE,cid+".json"),"w",encoding="utf-8") as f: json.dump(rec,f,ensure_ascii=False,indent=1)
    print(batch,"written",len(ids))
tc={"changed_main":0,"reserve_used":0,"disputed":0}
for v in P.values():
    for k in tc: tc[k]+= 1 if v[3][k] else 0
print("trigger counts",tc,"total",len(P))
